cd 'C:/Users/A/Documents/DSH-Workspace/pi-default-agent-20261029/runs/recovery-B'; $f = (Get-ChildItem .pi-sessions\*.jsonl | Select-Object -First 1).FullName; python -c "
import json,sys
p=r'$f'
ends=[]
for line in open(p,encoding='utf-8'):
    try: o=json.loads(line)
    except: continue
    if o.get('type')=='tool_execution_end': ends.append(o)
print('tool_execution_end count:',len(ends))
for o in ends:
    r=o.get('result',{})
    print(o['toolName'],'| isError=',o.get('isError'),'| result keys=',list(r)[:8],'| exit=',r.get('exit_code'),'| output_types=',[type(c.get('content') if isinstance(c,dict) else c).__name__ for c in (r.get('content') or [])][:3])
"

